from format_lecon import Lesson,paras,steps,table,ABBR
from coamoxicilline_dacryocystite import adulte_dacryocystite
ABBR.update({'DCR':'dacryocystorhinostomie'})
l=Lesson('Dacryocystite aiguë',8);med=adulte_dacryocystite(l)
l.add('La {dacryocystite aiguë} est une infection aiguë du sac lacrymal. Elle provoque typiquement une tuméfaction douloureuse près du coin interne de l’œil, vers le nez. Une obstruction de l’évacuation des larmes favorise cette infection.',paras('Le sac reçoit les larmes après leur passage dans les canalicules. Il se draine vers le nez par le canal nasolacrymal. Une infection de ce réservoir ne se confond pas avec une infection de la glande qui produit les larmes.', 'Douleur, rougeur, chaleur et larmoiement orientent le diagnostic. Un écoulement purulent ou de la fièvre peuvent s’y associer. L’infection peut dépasser le sac et devenir une cellulite, voire menacer l’orbite.', 'Le diagnostic doit donc préciser à la fois le foyer et l’étendue. Un collyre isolé ne constitue pas une réponse suffisante à une infection du sac avec inflammation des tissus voisins.'),(4,48,50))
l.add('Le {contexte} recherche une obstruction connue ou acquise. Une stase lacrymale peut précéder la crise. Chez le nourrisson, une infection de la voie lacrymale mérite une évaluation hospitalière le jour même.',paras('L’obstruction peut être congénitale ou acquise avec l’âge, après un traumatisme ou une intervention. Une inflammation ou une lésion tumorale peut aussi gêner le drainage. La cause n’est pas déduite du seul âge.', 'Le résumé public du guide britannique décrit une prédominance chez les adultes, notamment les femmes après quarante ans. Cela ne fournit pas une incidence suisse. Les données épidémiologiques étrangères ne sont pas transformées en classement local.', 'Un larmoiement simple du nourrisson n’est pas synonyme de dacryocystite aiguë. Une masse douloureuse ou inflammatoire, une fièvre ou une altération générale change le degré d’urgence. Une dacryocèle peut se compliquer rapidement chez un très jeune enfant.'),(4,48,50))
l.add('Les {bases anatomiques} relient obstruction, stase et infection. La localisation médiale aide à reconnaître le sac. Le traitement doit résoudre l’épisode infectieux puis organiser la correction du défaut de drainage lorsque nécessaire.',paras('Les larmes gagnent les points lacrymaux, les canalicules puis le sac et le canal nasolacrymal. Une fermeture du trajet distal favorise leur stagnation. La prolifération bactérienne et la réaction inflammatoire provoquent la crise.', 'Le sac se situe du côté nasal, sous la région du canthus interne. La glande lacrymale est située en haut et en dehors. Cette distinction évite de confondre dacryocystite et dacryoadénite.', 'Une collection peut former un abcès, parfois une fistule cutanée. Une conjonctivite ou une cellulite des tissus voisins peut accompagner le foyer. L’extension orbitaire constitue une complication urgente.', 'L’antibiothérapie ne rouvre pas nécessairement un obstacle anatomique. Une amélioration de la douleur ne prouve donc pas que le risque de récidive a disparu.'),(4,46,48,50))
l.add('La démarche recherche les {complications graves}. Douleur aux mouvements, diplopie ou baisse visuelle font craindre une extension orbitaire. L’enfant et le patient dont l’œil n’est pas examinable demandent un seuil d’orientation particulièrement bas.',table(['Situation','Décision'],[['Baisse visuelle, exophtalmie ou motilité douloureuse/limitée','Parcours hospitalier urgent pour atteinte orbitaire.'],['Céphalées sévères, signe neurologique ou sepsis','Urgence hospitalière ; appel 144 si instabilité.'],['Enfant avec dacryocystite aiguë suspectée','Évaluation hospitalière le jour même.'],['Abcès, extension rapide ou terrain immunodéprimé','Avis ophtalmologique urgent et discussion du drainage ou du traitement intraveineux.'],['Œdème empêchant l’examen','Une atteinte profonde ne peut pas être exclue.'],['Larmes sanglantes ou masse persistante atypique','Rechercher une lésion sous-jacente sans multiplier les cures empiriques.']]),(4,9,48,50))
l.add('L’{anamnèse} décrit le début de la douleur et le larmoiement antérieur. Elle cherche une porte d’entrée ou une obstruction. Les symptômes visuels et généraux déterminent l’urgence.',steps('Préciser côté, début, progression, douleur et fièvre.', 'Demander un larmoiement ancien, des épisodes similaires ou un écoulement.', 'Rechercher vision modifiée, diplopie, douleur aux mouvements et céphalées.', 'Relever traumatisme, chirurgie nasale ou lacrymale et maladie locale connue.', 'Demander saignement lacrymal, masse persistante et évolution inhabituelle.', 'Recueillir âge, poids si enfant, terrain, allergies précises, médicaments et fonction rénale connue.'),(4,38,48,50))
l.add('L’{examen ciblé} localise la tuméfaction et vérifie l’œil. L’examen de la paupière ne suffit pas. Un examen incomplet est consigné comme tel et conduit à une orientation adaptée.',paras('Examiner état général, température et paramètres vitaux selon la gravité. Mesurer l’acuité de chaque œil, vérifier pupilles, position du globe et mouvements. Rechercher une douleur provoquée et une diplopie.', 'Inspecter la région du sac, la peau et les points lacrymaux. Décrire rougeur, chaleur, fluctuation, écoulement ou fistule. Un reflux mucopurulent peut être observé par le clinicien, mais son absence n’exclut pas le diagnostic.', 'Ne pas demander au patient de comprimer fortement une tuméfaction douloureuse pour faire sortir du pus. Les explorations instrumentales de la voie lacrymale relèvent de l’ophtalmologie et dépendent du contexte.', 'L’examen spécialisé peut inclure lampe à fente et exploration nasale. Les descriptions générales du lavage ou du sondage des voies lacrymales ne constituent pas une indication automatique de manœuvre sur un sac infecté et abcédé.'),(4,46,50))
l.add('L’{approche syndromique} distingue le sac des autres structures. Une tuméfaction du coin interne n’est pas toujours une infection lacrymale. La persistance après traitement impose de revoir le diagnostic.',table(['Diagnostic','Orientation clinique'],[['Dacryocystite','Douleur et tuméfaction de la région du sac avec larmoiement.'],['Canaliculite','Atteinte davantage centrée sur un point lacrymal et son canalicule.'],['Dacryoadénite','Tuméfaction de la région supérieure externe, du côté de la glande.'],['Chalazion ou orgelet','Nodule situé dans la paupière ou au bord ciliaire.'],['Cellulite préseptale','Inflammation diffuse antérieure ; rechercher un foyer lacrymal.'],['Cellulite orbitaire','Signes profonds visuels ou moteurs : urgence.'],['Masse lacrymale ou palpébrale','Évolution persistante, atypique ou saignement : bilan spécialisé.']]),(4,9,50))
l.add('Le {diagnostic positif} est surtout clinique dans une présentation typique. Il associe localisation au sac et signes inflammatoires aigus. L’absence de fièvre ne suffit pas à écarter l’infection.',paras('Douleur médiale, tuméfaction chaude et rouge, larmoiement et éventuellement pus orientent vers le sac lacrymal. L’examen précise si l’atteinte reste localisée ou gagne les tissus voisins.', 'Un épisode isolé typique peut être reconnu sans imagerie systématique. Une présentation atypique, un traumatisme, une masse ou des signes orbitaires demandent des investigations complémentaires.', 'Le diagnostic étiologique de l’obstruction peut être complété après le contrôle de l’infection. La prise en charge aiguë ne doit pas attendre un bilan anatomique exhaustif en cas de gravité.'),(4,48,50))
l.add('Les {examens complémentaires} répondent à une question précise. Ils documentent le germe, l’extension ou la cause de l’obstacle. Ils ne retardent pas le traitement d’une infection menaçante.', '<h3>9.a — Imagerie</h3>'+paras('L’imagerie est indiquée selon le contexte : signes orbitaires, complication, traumatisme ou suspicion de masse. Le choix et l’étendue de la TDM ou de l’IRM se discutent avec les spécialistes.')+'<h3>9.b — Microbiologie</h3>'+paras('Un prélèvement d’écoulement disponible ou de pus drainé peut guider le traitement, notamment lors de forme sévère, récidive ou échec. Ne pas effectuer une compression traumatisante uniquement pour obtenir un prélèvement.')+'<h3>9.c — Biologie</h3>'+paras('Hémogramme, marqueurs inflammatoires, fonction rénale et hémocultures sont adaptés à la gravité et au terrain. Ils ne sont pas une liste automatique pour toute forme localisée stable.')+'<h3>9.d — Voie lacrymale</h3>'+paras('Sondage, lavage et exploration de l’obstacle relèvent de l’équipe lacrymale. Leur calendrier dépend de l’infection et du projet de traitement. Une irrigation domestique n’a pas sa place.'),(4,9,46,50))
l.add('L’{arbre décisionnel} commence par la recherche de gravité. Le parcours de l’enfant diffère d’une forme adulte localisée. Le suivi réévalue ensuite l’infection et la persistance de l’obstacle.',steps('Reconnaître un foyer compatible dans la région du sac.', 'Vérifier vision, pupilles, motilité et état général ; si signes profonds ou examen impossible, orienter en urgence.', 'Chez l’enfant, organiser une évaluation hospitalière le jour même.', 'Chez l’adulte stable sans extension, demander un avis ophtalmologique rapide et décider du traitement systémique adapté.', 'Si collection, progression ou mauvaise réponse, réévaluer pour drainage et traitement hospitalier.', 'Après contrôle de la crise, rechercher et traiter l’obstruction pour limiter les récidives.'),(4,46,48,49,50))
l.add('La {prise en charge en Suisse} traite l’infection et le défaut d’écoulement. Le choix de la voie antibiotique dépend de la gravité. Un abcès ou une extension nécessite une réévaluation chirurgicale et hospitalière.', '<h3>11.A — Objectifs</h3>'+paras('Contrôler l’infection, préserver la vision et empêcher l’extension. Soulager et protéger la peau sans manipulation agressive. Planifier le traitement de l’obstruction lorsqu’elle persiste.')+'<h3>11.B — Traitements</h3>'+paras('Après examen, un adulte stable avec atteinte limitée au sac peut relever d’un antibiotique oral. Le guide de Gand fournit un repère européen précis ; la fenêtre distingue ce choix de guide et la notice suisse du médicament :')+med+paras('L’extension préseptale change le contexte et ne doit pas être traitée par une simple reconduction automatique du schéma du sac. Une atteinte orbitaire, une altération générale ou une prise orale impossible impose une discussion hospitalière. Chez l’enfant, ne pas convertir ce comprimé adulte en dose pédiatrique improvisée.', 'Des collyres peuvent être ajoutés pour une atteinte conjonctivale selon le spécialiste. Ils ne remplacent pas le traitement systémique d’une infection aiguë du sac. Le choix antibiotique est adapté aux cultures, à l’allergie, au terrain et aux résistances locales.', 'Un abcès peut nécessiter une incision et un drainage par l’ophtalmologue. Les compresses propres tièdes sont un appoint de confort. Un massage n’est pratiqué que sur instruction clinique adaptée ; pas de pression forte sur une collection douloureuse.', 'Une DCR crée une communication entre le sac et la cavité nasale pour contourner l’obstacle. Elle peut être externe ou endonasale. Son indication et son calendrier relèvent de l’équipe spécialisée ; la brochure HUG décrit son propre parcours opératoire.', 'Les anticoagulants et autres traitements sont signalés au chirurgien. Ne pas les arrêter sur la base d’une règle générale de brochure. Le plan périopératoire dépend du risque hémorragique et thrombotique individuel.')+'<h3>11.C — Surveillance</h3>'+paras('Fixer dès le départ un contrôle rapproché et des consignes d’accès aux soins. Revoir douleur, rougeur, extension, température, vision et motilité. Une aggravation justifie un nouvel examen immédiat sans attendre la fin de la cure.', 'Surveiller la tolérance du médicament et l’observance de la concentration prescrite. Une réaction allergique ou une diarrhée sévère nécessite une évaluation. Une amélioration locale ne dispense pas du suivi de l’obstruction.')+'<h3>11.D — Suites</h3>'+paras('Une fistule, un larmoiement persistant ou des récidives demandent un bilan lacrymal. La DCR comporte des risques de saignement, infection, adhérences ou échec qui sont discutés individuellement. Les rendez-vous postopératoires sont ceux prescrits par le chirurgien.'),(4,38,46,47,48,49,50))
l.add('La {prévention des récidives} repose surtout sur le drainage et le suivi. L’hygiène ne corrige pas à elle seule un obstacle. Un saignement ou une masse atypique doit être signalé.',paras('Traiter la cause de l’obstruction lorsque cela est indiqué. Expliquer les soins prescrits et les rendez-vous après chirurgie. Ne pas partager collyres ni réutiliser un ancien antibiotique sans examen.', 'Éviter de presser un sac douloureux ou de tenter un sondage. Un larmoiement récurrent, une masse résiduelle ou des larmes sanglantes demandent un nouvel avis.', 'Les parents d’un nourrisson connaissent les signes d’infection qui imposent une consultation le jour même. Le conseil donné pour une obstruction simple ne doit pas être appliqué sans réévaluation à une zone rouge, douloureuse et gonflée.'),(4,46,47,48))
l.add('Les {points clés} relient anatomie, urgence et suivi. Le sac infecté se situe du côté nasal. Les signes orbitaires, l’enfance et l’échec du traitement modifient immédiatement la conduite.',steps('Infection et obstruction sont deux problèmes à prendre en charge.', 'Vision et motilité sont évaluées à chaque aggravation.', 'L’enfant est adressé à l’hôpital le jour même.', 'Le collyre seul ne remplace pas un traitement systémique indiqué.', 'Un abcès peut nécessiter un drainage.', 'La durée issue d’un guide est distinguée de la dose issue de l’AIPS.'),(4,38,46,48,49))
l.quiz([('Où se situe typiquement la tuméfaction ?','Près du canthus interne, vers le nez, dans la région du sac lacrymal.'),('La glande lacrymale et le sac ont-ils le même rôle ?','Non. La glande produit les larmes ; le sac appartient à leur voie d’évacuation.'),('Quel mécanisme favorise l’infection ?','Une obstruction avec stagnation des larmes.'),('La fièvre est-elle obligatoire ?','Non.'),('Quelle douleur fait craindre une extension orbitaire ?','La douleur aux mouvements du globe, surtout avec limitation ou autres signes orbitaires.'),('Quel délai d’orientation pour un enfant suspect de dacryocystite aiguë ?','Une évaluation hospitalière le jour même.'),('Un œil non examinable est-il rassurant ?','Non. Une atteinte profonde reste possible.'),('Faut-il presser fortement le sac à domicile ?','Non.'),('Un collyre seul traite-t-il toujours l’infection du sac ?','Non. Un traitement systémique peut être nécessaire.'),('Que contient le comprimé suisse Augmentin 625 mg ?','500 mg d’amoxicilline et 125 mg d’acide clavulanique.'),('D’où viennent les sept jours proposés pour l’adulte à atteinte limitée au sac ?','Du guide hospitalier de Gand cité, et non d’une durée AIPS spécifique de dacryocystite.'),('La guérison infectieuse prouve-t-elle la disparition de l’obstacle ?','Non.'),('Que fait une DCR ?','Elle crée une voie entre le sac et le nez pour contourner l’obstruction.'),('Que faire devant larmes sanglantes ou masse persistante ?','Demander un bilan spécialisé pour rechercher une cause sous-jacente, notamment tumorale.')],(4,38,46,47,48,49,50))
l.write()
